package dev.pocketengine.browser;

import dev.pocketengine.features.plugins.PluginRules;
import dev.pocketengine.store.TaskStore;
import java.util.UUID;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;

public final class BrowserReadRecipeTest {
    static JSONObject source(String mode)throws Exception {JSONObject raw=BrowserStructuredSourceTest.delivered(mode),p=BrowserStructuredSource.fromDelivered(raw);return BrowserStructuredSourceTest.source(UUID.randomUUID().toString(),UUID.randomUUID().toString(),p).put("kind",BrowserSemanticRead.KIND).put("privateUrl","https://source.example/report?private=owner").put("profileId","owner-default");}
    static JSONObject ref()throws Exception{return new JSONObject().put("id",UUID.randomUUID().toString()).put("revision",2).put("digest","a".repeat(64));}
    static JSONObject actual(String mode)throws Exception{return BrowserStructuredSourceTest.delivered(mode).put("url","https://source.example/report?new=search").put("observationId",UUID.randomUUID().toString());}
    @Test public void fixedRecipeHasVersionInputOutputSchemaAndRealSourceButNoFactsOrPermissions()throws Exception {JSONObject r=BrowserReadRecipe.fromSource(source("table"),"项目");BrowserReadRecipe.validate(r);assertEquals(2,r.getJSONArray("expectedHeaders").length());assertEquals("column_1",r.getJSONArray("outputFields").getJSONObject(1).getString("name"));assertTrue(r.getBoolean("readOnly"));assertFalse(r.getBoolean("cachedFacts"));assertEquals(0,r.getJSONArray("grantsAdded").length());assertFalse(r.toString().contains("¥42"));assertFalse(r.toString().contains("private=owner"));assertEquals(0,r.getJSONObject("inputSchema").getJSONObject("properties").length());}
    @Test public void matchedOutputIsDeterministicVerbatimCellsWithOriginalRowLocation()throws Exception {JSONObject r=BrowserReadRecipe.fromSource(source("table"),"项目"),observation=actual("table"),out=BrowserReadRecipe.project(r,ref(),observation);assertEquals("matched",out.getJSONObject("readRecipe").getString("status"));assertEquals("¥42 😀",out.getJSONArray("recipeOutput").getJSONObject(0).getJSONObject("values").getString("column_1"));assertEquals(1,out.getJSONArray("recipeOutput").getJSONObject(0).getInt("sourceRowIndex"));assertFalse(out.getBoolean("verified"));assertEquals(observation.getString("observationId"),out.getJSONObject("readRecipe").getString("sourceObservationId"));BrowserReadRecipe.validateEvidence(out.getJSONObject("readRecipe"));}
    @Test public void changedHeaderStopsRecipeAndReturnsOnlyRealOrdinaryObservationWithoutRetry()throws Exception {JSONObject r=BrowserReadRecipe.fromSource(source("table"),"项目"),actual=actual("table");actual.getJSONObject("read").getJSONArray("data").getJSONObject(0).getJSONArray("cells").getJSONObject(1).put("text","new unit");JSONObject out=BrowserReadRecipe.project(r,ref(),actual);assertEquals("drift",out.getJSONObject("readRecipe").getString("status"));assertFalse(out.has("recipeOutput"));assertTrue(out.getJSONObject("readRecipe").getBoolean("ordinaryObserveFallbackRequired"));assertFalse(out.getJSONObject("readRecipe").getBoolean("automaticRetryPerformed"));assertTrue(out.getJSONObject("read").getJSONArray("data").toString().contains("new unit"));}
    @Test public void partialOrLoginPageNeverMatchesTheCachedSchema()throws Exception {JSONObject r=BrowserReadRecipe.fromSource(source("table"),"项目"),partial=actual("table");partial.getJSONObject("read").getJSONObject("facts").put("partial",true).put("reasons",new JSONArray().put("node_budget"));assertEquals("coverage_or_structure_changed",BrowserReadRecipe.project(r,ref(),partial).getJSONObject("readRecipe").getString("reason"));JSONObject login=actual("table").put("status","unavailable");login.remove("read");assertEquals("observation_unavailable",BrowserReadRecipe.project(r,ref(),login).getJSONObject("readRecipe").getString("reason"));}
    @Test public void anotherProfileOriginOrPathCannotBorrowRecipeAuthority()throws Exception {JSONObject r=BrowserReadRecipe.fromSource(source("table"),"项目");BrowserReadRecipe.pagePrecondition(r,"owner-default","https://source.example","https://source.example/report",false);assertThrows(SecurityException.class,()->BrowserReadRecipe.pagePrecondition(r,"profile-other","https://source.example","https://source.example/report",false));assertThrows(SecurityException.class,()->BrowserReadRecipe.pagePrecondition(r,"owner-default","https://other.example","https://other.example/report",true));assertThrows(IllegalArgumentException.class,()->BrowserReadRecipe.pagePrecondition(r,"owner-default","https://source.example","https://source.example/login",false));}
    @Test public void modelCannotAddScriptSideEffectGrantInputOrOldFrameRegionIdentity()throws Exception {JSONObject r=BrowserReadRecipe.fromSource(source("table"),"项目");for(String k:new String[]{"script","click","navigate","approvalId","cookie"})assertThrows(SecurityException.class,()->BrowserReadRecipe.validate(new JSONObject(r.toString()).put(k,"untrusted")));BrowserReadRecipe.matchesRequest(r,new JSONObject().put("mode","table").put("query","项目"));assertThrows(IllegalArgumentException.class,()->BrowserReadRecipe.matchesRequest(r,new JSONObject().put("mode","table").put("regionRef",UUID.randomUUID()+":r1")));}
    @Test public void duplicateListItemsKeepTheirSeparateOriginalPositions()throws Exception {JSONObject r=BrowserReadRecipe.fromSource(source("list"),"条目"),out=BrowserReadRecipe.project(r,ref(),actual("list"));assertEquals(2,out.getJSONArray("recipeOutput").length());assertEquals("重复项",out.getJSONArray("recipeOutput").getJSONObject(0).getJSONObject("values").getString("itemText"));assertNotEquals(out.getJSONArray("recipeOutput").getJSONObject(0).getInt("sourceRowIndex"),out.getJSONArray("recipeOutput").getJSONObject(1).getInt("sourceRowIndex"));}
    @Test public void actualPluginRulesChecksReferenceSchemaAndRejectsAuthorityFields()throws Exception {PluginRules.validateArguments(ref(),BrowserReadRecipe.referenceSchema());assertThrows(IllegalArgumentException.class,()->PluginRules.validateArguments(ref().put("grant",true),BrowserReadRecipe.referenceSchema()));assertThrows(IllegalArgumentException.class,()->BrowserReadRecipe.reference(ref().put("revision",0)));}
    @Test public void partialSavedProjectionCannotCreateAPretendCompleteRecipe()throws Exception {JSONObject source=source("table"),p=source.getJSONObject("structuredProjection");p.put("partial",true);BrowserStructuredSourceTest.revision(p);assertThrows(IllegalArgumentException.class,()->BrowserReadRecipe.fromSource(source,"项目"));}
    @Test public void evidencePinsActualRecipeVersionAndCannotClaimAutoRetryOrAnotherSchema()throws Exception {JSONObject r=BrowserReadRecipe.fromSource(source("table"),"项目"),e=BrowserReadRecipe.project(r,ref(),actual("table")).getJSONObject("readRecipe");BrowserReadRecipe.validateEvidence(e);assertThrows(SecurityException.class,()->BrowserReadRecipe.validateEvidence(new JSONObject(e.toString()).put("automaticRetryPerformed",true)));assertThrows(SecurityException.class,()->BrowserReadRecipe.validateEvidence(new JSONObject(e.toString()).put("approvalId",UUID.randomUUID().toString())));assertEquals(TaskStore.capabilityFingerprint(r),e.getString("configFingerprint"));}
}
